// ABOUTME: Captures reviewer-visible screenshots of the signed-in header area switcher.
// ABOUTME: Drives a real desktop and mobile browser against the local Worker, no mocks.
const playwright = await import(`${process.env.PLAYWRIGHT_MODULE}`);
const { chromium, webkit, devices } = playwright.default ?? playwright;

const BASE = process.env.BASE_URL ?? "http://127.0.0.1:8891";
const OUT = process.env.OUT_DIR;
const PASSWORD = "Greenroom!2027";

const shot = async (page, name) => {
  await page.screenshot({ path: `${OUT}/${name}.png`, fullPage: false });
  console.log(`captured ${name}.png`);
};

async function signIn(page, email, password) {
  await page.goto(`${BASE}/login`);
  await page.getByLabel("Email").fill(email);
  await page.getByLabel("Password").fill(password);
  await page.getByRole("button", { name: "Sign in" }).click();
}
